/** Market semiotics are drawn in the world; no new atlas or modal is needed. */
export function drawTradeMarker(c,o,s,scene,T,time){const district=s.economy?.districts?.[scene.chapter||1];if(o.type!=='shop'&&!(o.regional&&o.lifeKind==='project'&&district?.works?.length))return;const x=(o.xy[0]+.5)*T,y=(o.xy[1]+.5)*T-76;c.save();c.translate(x,y);c.fillStyle='#172f32';c.strokeStyle='#d8bb80';c.lineWidth=1.5;c.beginPath();c.roundRect(-23,-13,46,26,6);c.fill();c.stroke();c.fillStyle='#dfc78b';c.font='bold 17px Georgia';c.textAlign='center';c.fillText(o.type==='shop'?'↔':'⌂',0,5);for(let i=0;i<(district?.works?.length||0);i++){c.fillStyle=({water:'#a0d8e4',workshop:'#dfb681',commons:'#a0cc9f'})[district.works[i]];c.beginPath();c.arc(-12+i*12,18,3,0,Math.PI*2);c.fill();}if(district?.favor){c.strokeStyle='#b7d7b2';c.beginPath();c.arc(0,0,30+Math.sin(time)*1.2,-.5,1);c.stroke();}c.restore();}
